11	export interface AgentProtocol extends Trajectory {
12	  /**
13	   * Send data to the agent. Promise resolves when action is acknowledged.
14	   * Returns the `streamId` of the stream the message was correlated to --
15	   * this may be a new stream if idle, an existing stream, or null if no
16	   * stream was triggered.
17	   *
18	   * When a new stream is created by a send, the streamId MUST be returned
19	   * before the `agent_start` event is emitted for the stream.
20	   */
21	  send(payload: AgentSend): Promise<{ streamId: string | null }>;
22	
23	  /**
24	   * Subscribes the provided callback to all future events emitted by this
25	   * session. Returns an unsubscribe function.
26	   *
27	   * @param callback The callback function to listen to events.
28	   */
29	  subscribe(callback: (event: AgentEvent) => void): Unsubscribe;
30	
31	  /**
32	   * Aborts an active stream of agent activity.
33	   */
34	  abort(): Promise<void>;
35	
36	  /**
37	   * AgentProtocol implements the Trajectory interface and can retrieve existing events.
38	   */
39	  readonly events: AgentEvent[];
40	}
