47	interface AgentSendPayloads {
48	  message: ContentPart[];
49	  elicitations: ElicitationResponse[];
50	  update: { title?: string; model?: string; config?: Record<string, unknown> };
51	  action: { type: string; data: unknown };
52	}
53	
54	export type AgentSend = RequireExactlyOne<AgentSendPayloads> & WithMeta;
55	
56	export interface Trajectory {
57	  readonly events: AgentEvent[];
58	}
