80	export type AgentEventData<
81	  EventType extends keyof AgentEvents = keyof AgentEvents,
82	> = AgentEvents[EventType] & { type: EventType };
83	
84	export type AgentEvent<
85	  EventType extends keyof AgentEvents = keyof AgentEvents,
86	> = AgentEventCommon & AgentEventData<EventType>;
