88	export interface AgentEvents {
89	  /** MUST be the first event emitted in a session. */
90	  initialize: Initialize;
91	  /** Updates configuration about the current session/agent. */
92	  session_update: SessionUpdate;
93	  /** Message content provided by user, agent, or developer. */
94	  message: Message;
95	  /** Event indicating the start of agent activity on a stream. */
96	  agent_start: AgentStart;
97	  /** Event indicating the end of agent activity on a stream. */
98	  agent_end: AgentEnd;
99	  /** Tool request issued by the agent. */
100	  tool_request: ToolRequest;
101	  /** Tool update issued by the agent. */
102	  tool_update: ToolUpdate;
103	  /** Tool response supplied by the agent. */
104	  tool_response: ToolResponse;
105	  /** Elicitation request to be displayed to the user. */
106	  elicitation_request: ElicitationRequest;
107	  /** User's response to an elicitation to be returned to the agent. */
108	  elicitation_response: ElicitationResponse;
109	  /** Reports token usage information. */
110	  usage: Usage;
111	  /** Report errors. */
112	  error: ErrorData;
113	  /** Custom events for things not otherwise covered above. */
114	  custom: CustomEvent;
