7	import type { Part } from '@google/genai';
8	import type { ContentPart } from './types.js';
9	
10	/**
11	 * Converts Gemini API Part objects to framework-agnostic ContentPart objects.
12	 * Handles text, thought, inlineData, fileData parts and serializes unknown
13	 * part types to text to avoid silent data loss.
14	 */
15	export function geminiPartsToContentParts(parts: Part[]): ContentPart[] {
16	  const result: ContentPart[] = [];
17	  for (const part of parts) {
18	    if ('text' in part && part.text !== undefined) {
19	      if ('thought' in part && part.thought) {
20	        result.push({
21	          type: 'thought',
22	          thought: part.text,
23	          ...(part.thoughtSignature
24	            ? { thoughtSignature: part.thoughtSignature }
25	            : {}),
26	        });
27	      } else {
28	        result.push({ type: 'text', text: part.text });
29	      }
30	    } else if ('inlineData' in part && part.inlineData) {
31	      result.push({
32	        type: 'media',
33	        data: part.inlineData.data,
34	        mimeType: part.inlineData.mimeType,
35	      });
36	    } else if ('fileData' in part && part.fileData) {
37	      result.push({
38	        type: 'media',
39	        uri: part.fileData.fileUri,
40	        mimeType: part.fileData.mimeType,
41	      });
42	    } else if ('functionCall' in part && part.functionCall) {
43	      continue; // Skip function calls, they are emitted as distinct tool_request events
44	    } else if ('functionResponse' in part && part.functionResponse) {
45	      continue; // Skip function responses, they are tied to tool_response events
46	    } else {
47	      // Fallback: serialize any unrecognized part type to text
48	      result.push({
49	        type: 'text',
50	        text: JSON.stringify(part),
51	        _meta: { partType: 'unknown' },
52	      });
53	    }
54	  }
55	  return result;
56	}
57	
58	/**
59	 * Converts framework-agnostic ContentPart objects to Gemini API Part objects.
60	 */
61	export function contentPartsToGeminiParts(content: ContentPart[]): Part[] {
62	  const result: Part[] = [];
63	  for (const part of content) {
64	    switch (part.type) {
65	      case 'text':
66	        result.push({ text: part.text });
67	        break;
68	      case 'thought':
69	        result.push({
70	          text: part.thought,
71	          thought: true,
72	          ...(part.thoughtSignature
73	            ? { thoughtSignature: part.thoughtSignature }
74	            : {}),
75	        });
76	        break;
77	      case 'media':
78	        if (part.data) {
79	          result.push({
80	            inlineData: {
81	              data: part.data,
82	              mimeType: part.mimeType ?? 'application/octet-stream',
83	            },
84	          });
85	        } else if (part.uri) {
86	          result.push({
87	            fileData: { fileUri: part.uri, mimeType: part.mimeType },
88	          });
89	        }
90	        break;
91	      case 'reference':
92	        // References are converted to text for the model
93	        result.push({ text: part.text });
94	        break;
95	      default:
96	        // Serialize unknown ContentPart variants instead of dropping them
97	        result.push({ text: JSON.stringify(part) });
98	        break;
99	    }
100	  }
101	  return result;
102	}
103	
104	/**
105	 * Converts a ToolCallResponseInfo.resultDisplay value into ContentPart[].
106	 * Handles string, object-valued (FileDiff, SubagentProgress, etc.),
107	 * and undefined resultDisplay consistently.
108	 */
109	export function toolResultDisplayToContentParts(
110	  resultDisplay: unknown,
111	): ContentPart[] | undefined {
112	  if (resultDisplay === undefined || resultDisplay === null) {
113	    return undefined;
114	  }
115	  const text =
116	    typeof resultDisplay === 'string'
117	      ? resultDisplay
118	      : JSON.stringify(resultDisplay);
119	  return [{ type: 'text', text }];
120	}
121	
122	/**
123	 * Builds the data record for a tool_response AgentEvent, preserving
124	 * all available metadata from the ToolCallResponseInfo.
125	 */
126	export function buildToolResponseData(response: {
127	  data?: Record<string, unknown>;
128	  errorType?: string;
129	  outputFile?: string;
130	  contentLength?: number;
131	}): Record<string, unknown> | undefined {
132	  const parts: Record<string, unknown> = {};
133	  if (response.data) Object.assign(parts, response.data);
134	  if (response.errorType) parts['errorType'] = response.errorType;
135	  if (response.outputFile) parts['outputFile'] = response.outputFile;
136	  if (response.contentLength !== undefined)
137	    parts['contentLength'] = response.contentLength;
138	  return Object.keys(parts).length > 0 ? parts : undefined;
139	}
