7	import type {
8	  AgentEvent,
9	  AgentEventCommon,
10	  AgentEventData,
11	  AgentSend,
12	  AgentProtocol,
13	  Unsubscribe,
14	} from './types.js';
15	
16	export type MockAgentEvent = Partial<AgentEventCommon> & AgentEventData;
17	
18	export interface PushResponseOptions {
19	  /** If true, does not automatically add an agent_end event. */
20	  keepOpen?: boolean;
21	}
22	
23	/**
24	 * A mock implementation of AgentProtocol for testing.
25	 * Allows queuing responses that will be yielded when send() is called.
26	 */
27	export class MockAgentProtocol implements AgentProtocol {
28	  private _events: AgentEvent[] = [];
29	  private _responses: Array<{
30	    events: MockAgentEvent[];
31	    options?: PushResponseOptions;
32	  }> = [];
33	  private _subscribers = new Set<(event: AgentEvent) => void>();
34	  private _activeStreamIds = new Set<string>();
35	  private _lastStreamId?: string | null;
36	  private _nextEventId = 1;
37	  private _nextStreamId = 1;
38	
39	  title?: string;
40	  model?: string;
41	  config?: Record<string, unknown>;
42	
43	  constructor(initialEvents: AgentEvent[] = []) {
44	    this._events = [...initialEvents];
45	  }
46	
47	  /**
48	   * All events that have occurred in this session so far.
49	   */
50	  get events(): AgentEvent[] {
51	    return this._events;
52	  }
53	
54	  subscribe(callback: (event: AgentEvent) => void): Unsubscribe {
55	    this._subscribers.add(callback);
56	    return () => this._subscribers.delete(callback);
57	  }
58	
59	  private _emit(event: AgentEvent) {
60	    if (!this._events.some((e) => e.id === event.id)) {
61	      this._events.push(event);
62	    }
63	    for (const callback of this._subscribers) {
64	      callback(event);
65	    }
66	    if (event.type === 'agent_end' && event.streamId) {
67	      this._activeStreamIds.delete(event.streamId);
68	    }
69	  }
70	
71	  /**
72	   * Queues a sequence of events to be "emitted" by the agent in response to the
73	   * next send() call.
74	   */
75	  pushResponse(events: MockAgentEvent[], options?: PushResponseOptions) {
76	    this._responses.push({ events, options });
77	  }
78	
79	  /**
80	   * Appends events to an existing stream and notifies any waiting listeners.
81	   */
82	  pushToStream(
83	    streamId: string,
84	    events: MockAgentEvent[],
85	    options?: { close?: boolean },
86	  ) {
87	    const now = new Date().toISOString();
88	    for (const eventData of events) {
89	      const event: AgentEvent = {
90	        ...eventData,
91	        id: eventData.id ?? `e-${this._nextEventId++}`,
92	        timestamp: eventData.timestamp ?? now,
93	        streamId: eventData.streamId ?? streamId,
94	      } as AgentEvent;
95	      this._emit(event);
96	    }
97	
98	    if (
99	      options?.close &&
100	      !events.some((eventData) => eventData.type === 'agent_end')
101	    ) {
102	      this._emit({
103	        id: `e-${this._nextEventId++}`,
104	        timestamp: now,
105	        streamId,
106	        type: 'agent_end',
107	        reason: 'completed',
108	      } as AgentEvent);
109	    }
110	  }
111	
112	  async send(payload: AgentSend): Promise<{ streamId: string | null }> {
113	    const responseData = this._responses.shift();
114	    const { events: response, options } = responseData ?? {
115	      events: [],
116	    };
117	
118	    // If there were queued responses (even if empty array), we trigger a stream.
119	    const hasResponseEvents = responseData !== undefined;
120	    const streamId = hasResponseEvents
121	      ? (response[0]?.streamId ?? `mock-stream-${this._nextStreamId++}`)
122	      : null;
123	
124	    const now = new Date().toISOString();
125	    const eventsToEmit: AgentEvent[] = [];
126	
127	    // Helper to normalize and prepare for emission
128	    const normalize = (eventData: MockAgentEvent): AgentEvent =>
129	      ({
130	        ...eventData,
131	        id: eventData.id ?? `e-${this._nextEventId++}`,
132	        timestamp: eventData.timestamp ?? now,
133	        streamId: eventData.streamId ?? streamId,
134	      }) as AgentEvent;
135	
136	    // 1. User/Update event (BEFORE agent_start)
137	    if ('message' in payload && payload.message) {
138	      eventsToEmit.push(
139	        normalize({
140	          type: 'message',
141	          role: 'user',
142	          content: payload.message,
143	          _meta: payload._meta,
144	        }),
145	      );
146	    } else if ('elicitations' in payload && payload.elicitations) {
147	      payload.elicitations.forEach((elicitation) => {
148	        eventsToEmit.push(
149	          normalize({
150	            type: 'elicitation_response',
151	            ...elicitation,
152	            _meta: payload._meta,
153	          }),
154	        );
155	      });
156	    } else if (
157	      'update' in payload &&
158	      payload.update &&
159	      Object.keys(payload.update).length > 0
160	    ) {
161	      if (payload.update.title) this.title = payload.update.title;
162	      if (payload.update.model) this.model = payload.update.model;
163	      if (payload.update.config) {
164	        this.config = payload.update.config;
165	      }
166	      eventsToEmit.push(
167	        normalize({
168	          type: 'session_update',
169	          ...payload.update,
170	          _meta: payload._meta,
171	        }),
172	      );
173	    } else if ('action' in payload && payload.action) {
174	      throw new Error(
175	        `Actions not supported in MockAgentProtocol: ${payload.action.type}`,
176	      );
177	    }
178	
179	    // 2. agent_start (if stream)
180	    if (streamId) {
181	      if (!response.some((eventData) => eventData.type === 'agent_start')) {
182	        eventsToEmit.push(
183	          normalize({
184	            type: 'agent_start',
185	            streamId,
186	          }),
187	        );
188	      }
189	    }
190	
191	    // 3. Response events
192	    for (const eventData of response) {
193	      eventsToEmit.push(normalize(eventData));
194	    }
195	
196	    // 4. agent_end (if stream and not manual)
197	    if (streamId && !options?.keepOpen) {
198	      if (!eventsToEmit.some((e) => e.type === 'agent_end')) {
199	        eventsToEmit.push(
200	          normalize({
201	            type: 'agent_end',
202	            reason: 'completed',
203	            streamId,
204	          }),
205	        );
206	      }
207	    }
208	
209	    if (streamId) {
210	      this._activeStreamIds.add(streamId);
211	    }
212	    this._lastStreamId = streamId;
213	
214	    // Emit events asynchronously so the caller receives the streamId first.
215	    if (eventsToEmit.length > 0) {
216	      void Promise.resolve().then(() => {
217	        for (const event of eventsToEmit) {
218	          this._emit(event);
219	        }
220	      });
221	    }
222	
223	    return { streamId };
224	  }
225	
226	  async abort(): Promise<void> {
227	    if (this._lastStreamId && this._activeStreamIds.has(this._lastStreamId)) {
228	      const streamId = this._lastStreamId;
229	      this._emit({
230	        id: `e-${this._nextEventId++}`,
231	        timestamp: new Date().toISOString(),
232	        streamId,
233	        type: 'agent_end',
234	        reason: 'aborted',
235	      } as AgentEvent);
236	    }
237	  }
238	}
