  streamStartEmitted: boolean;
  /** The model reported for this stream, if any (via a `ModelInfo` event). */
  model: string | undefined;
  /** Monotonic counter used to derive unique, ordered event ids. */
  eventCounter: number;
  /** Maps a pending tool call id to the requested tool name. */
  pendingToolNames: Map<string, string>;
  /** The stream id shared by every event produced from this state. */
  streamId: string;
