 * Creates a fresh {@link TranslationState} for a single agent stream.
 *
 * @param streamId An explicit stream id to use; a random UUID is generated when
 *   omitted.
 */
export function createTranslationState(streamId?: string): TranslationState {
  return {
    streamStartEmitted: false,
    model: undefined,
    eventCounter: 0,
    pendingToolNames: new Map<string, string>(),
    streamId: streamId ?? randomUUID(),
